    processor = AutoProcessor.from_pretrained(model_path, trust_remote_code=True)
    model = AutoModel.from_pretrained(
        model_path,
        trust_remote_code=True,
        torch_dtype=torch.bfloat16,
        device_map="auto"
    )
    model.eval()

def get_screenshot(device_id: str) -> bytes:
    screenshot_path = f"/tmp/screen_{device_id}_{time.time()}.png"
    subprocess.run(
        ["adb", "-s", device_id, "exec-out", "screencap", "-p"],
        stdout=open(screenshot_path, "wb"),
        check=True
    )
    with open(screenshot_path, "rb") as f:
        screenshot_data = f.read()
    os.remove(screenshot_path)
    return screenshot_data

def execute_tap(device_id: str, x: int, y: int):
    subprocess.run(
        ["adb", "-s", device_id, "shell", "input", "tap", str(x), str(y)],
        check=True
    )

def execute_swipe(device_id: str, x1: int, y1: int, x2: int, y2: int, duration: int):
    subprocess.run(
        ["adb", "-s", device_id, "shell", "input", "swipe", str(x1), str(y1), str(x2), str(y2), str(duration)],
        check=True
    )

def execute_text(device_id: str, text: str):
    escaped_text = text.replace(" ", "%s").replace("'", "\\'")
    subprocess.run(
        ["adb", "-s", device_id, "shell", "input", "text", escaped_text],
        check=True
    )

def execute_keyevent(device_id: str, keycode: int):
    subprocess.run(
        ["adb", "-s", device_id, "shell", "input", "keyevent", str(keycode)],
        check=True
    )

