    subprocess.run(
        ["adb", "-s", device_id, "shell", "monkey", "-p", package_name, "-c", "android.intent.category.LAUNCHER", "1"],
        check=True
    )

def parse_model_output(output: str) -> Dict:
    lines = output.strip().split("\n")
    action = {}
    for line in lines:
        if "tap" in line.lower():
            parts = line.split()
            coords = [int(p) for p in parts if p.isdigit()]
            if len(coords) >= 2:
                action["type"] = "tap"
                action["x"] = coords[0]
                action["y"] = coords[1]
        elif "swipe" in line.lower():
            parts = line.split()
            coords = [int(p) for p in parts if p.isdigit()]
            if len(coords) >= 4:
                action["type"] = "swipe"
                action["x1"] = coords[0]
                action["y1"] = coords[1]
                action["x2"] = coords[2]
                action["y2"] = coords[3]
                action["duration"] = coords[4] if len(coords) > 4 else 300
        elif "text" in line.lower() or "input" in line.lower():
            parts = line.split(":", 1)
            if len(parts) == 2:
                action["type"] = "text"
                action["text"] = parts[1].strip()
        elif "back" in line.lower():
