<script>
const API_BASE = window.location.origin;
let currentDevice = null;

async function loadDevices() {
  try {
    const response = await fetch(`${API_BASE}/devices`);
    const data = await response.json();
    const select = document.getElementById('deviceSelect');
    select.innerHTML = '';

    if (data.devices.length === 0) {
      select.innerHTML = '<option value="">No devices connected</option>';
      return;
    }

    data.devices.forEach(device => {
      const option = document.createElement('option');
      option.value = device;
      option.textContent = device;
      select.appendChild(option);
    });

    currentDevice = data.devices[0];
    loadScreenshot();
  } catch (error) {
    document.getElementById('statusText').textContent = `Error loading devices: ${error.message}`;
  }
}

async function loadScreenshot() {
  if (!currentDevice) return;

  try {
    document.getElementById('statusText').textContent = 'Loading screenshot...';
    const response = await fetch(`${API_BASE}/screenshot/${currentDevice}`);
    const data = await response.json();
    const img = document.getElementById('screenshotImg');
    img.src = `data:image/png;base64,${data.image}`;
    img.style.display = 'block';
    document.getElementById('statusText').textContent = 'Screenshot loaded';
  } catch (error) {
    document.getElementById('statusText').textContent = `Error loading screenshot: ${error.message}`;
  }
}

async function executeCommand() {
  const command = document.getElementById('commandInput').value.trim();

  if (!command) {
    document.getElementById('statusText').textContent = 'Please enter a command';
    return;
  }

  if (!currentDevice) {
    document.getElementById('statusText').textContent = 'No device selected';
    return;
  }

  try {
    document.getElementById('statusText').textContent = 'Executing command...';
    document.getElementById('executeBtn').disabled = true;

    const response = await fetch(`${API_BASE}/execute`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        instruction: command,
        device_id: currentDevice
      })
    });

    const data = await response.json();

    document.getElementById('statusText').textContent = `Action: ${data.action_type}, Status: ${data.status}`;

    setTimeout(() => {
      loadScreenshot();
    }, 1000);

  } catch (error) {
    document.getElementById('statusText').textContent = `Error: ${error.message}`;
  } finally {
    document.getElementById('executeBtn').disabled = false;
  }
}

document.getElementById('deviceSelect').addEventListener('change', (e) => {
  currentDevice = e.target.value;
  if (currentDevice) {
    loadScreenshot();
  }
});

document.getElementById('executeBtn').addEventListener('click', executeCommand);
document.getElementById('refreshScreenBtn').addEventListener('click', loadScreenshot);

document.getElementById('commandInput').addEventListener('keydown', (e) => {
  if (e.ctrlKey && e.key === 'Enter') {
    executeCommand();
  }
});

loadDevices();
</script>
