def parse_action(response_text: str) -> Dict[str, Any]:
    lines = response_text.strip().split("\n")
    action_data = {"type": "none", "params": {}}

    for line in lines:
        cmd = line.strip().lower()
        if "tap" in cmd:
            parts = [s for s in cmd.split() if s.isdigit()]
            if len(parts) >= 2:
                action_data = {"type": "tap", "params": {"x": int(parts[0]), "y": int(parts[1])}}
                break
        elif "swipe" in cmd:
            parts = [s for s in cmd.split() if s.isdigit()]
            if len(parts) >= 4:
                duration = int(parts[4]) if len(parts) > 4 else 300
                action_data = {"type": "swipe", "params": {"x1": int(parts[0]), "y1": int(parts[1]), "x2": int(parts[2]), "y2": int(parts[3]), "duration": duration}}
                break
        elif "text" in cmd or "type" in cmd:
            text_content = line.split(":", 1)[-1].strip() if ":" in line else line
            action_data = {"type": "text", "params": {"text": text_content}}
