async function execute() {
    const txt = el('prompt').value.trim();
    if (!txt || !activeDevice || isBusy) return;

    isBusy = true;
    const btn = el('actionBtn');
    btn.classList.add('loading');
    btn.disabled = true;

    try {
        const res = await fetch(`${API}/execute`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ instruction: txt, device_id: activeDevice })
        });
        const data = await res.json();
        if (data.status === 'success') {
            await new Promise(r => setTimeout(r, 1500));
            await updateScreen();
        }
    } catch (e) {
        alert("Execution failed: " + e.message);
    } finally {
        isBusy = false;
        btn.classList.remove('loading');
        btn.disabled = false;
    }
}

el('deviceList').addEventListener('change', (e) => {
    activeDevice = e.target.value;
    updateScreen();
});

el('actionBtn').addEventListener('click', execute);

el('prompt').addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) execute();
});

fetchDevices();
setInterval(() => { if(!isBusy && activeDevice) updateScreen(); }, 3000);
</script>
</body>
</html>
